B.C0=s(["Minggu","Senin","Selasa","Rabu","Kamis","Jumat","Sabtu"],t.s)
B.aqj=s(["Planned: full Qur\u2019an pack","Planned: Al-Fatihah and the short surahs","Planned: Juz Amma memorization pack","Planned: reciter comparison set"],t.s)
B.aql=s(["\u091c\u0928","\u092b\u0947\u092c","\u092e\u093e\u0930\u094d\u091a","\u0905\u092a\u094d\u0930","\u092e\u0947","\u091c\u0941\u0928","\u091c\u0941\u0932","\u0905\u0917","\u0938\u0947\u092a","\u0905\u0915\u094d\u091f\u094b","\u0928\u094b\u092d\u0947","\u0921\u093f\u0938\u0947"],t.s)
